command:
// ==========================================
// ⚙️ LUNAS WIRKUNG: EISENKRALLEN (V13 Ready)
// ==========================================

(async () => {
    // ============================================================
    // 0. Framework laden & Wirkungsende-Hook registrieren
    // ============================================================
    const fwMacro = await fromUuid("Compendium.dsk-havena-und-umland.makros.Macro.fHQ2OuDo3Fe3spBn");
    if (fwMacro) { await fwMacro.execute(); }

    if (typeof DSK === "undefined") {
        ui.notifications.error("Das DSK-Framework konnte nicht geladen werden!");
        return;
    }
    const DSK_FW = globalThis.DSK || DSK;

    const gabenName = "Eisenkrallen (Rondra)";
    const ahne = "rondra";
    const waffenName = "Eisenkrallen (Temporär)";

    if (DSK_FW.EffektEnde) {
        DSK_FW.EffektEnde.Register(
            "rondraEisenkrallen", 
            gabenName, 
            "Die Krallen verlieren ihren metallischen Glanz, werden wieder weich und die übernatürliche Waffe verschwindet."
        );
    }

    // ============================================================
    // 1. Globalen Puffer initialisieren
    // ============================================================
    if (!globalThis._eisenkrallenPuffer) {
        globalThis._eisenkrallenPuffer = {
            erfolge: [],
            fehlschläge: [],
            ziele: [],
            timer: null,
            qs: 1,
            speaker: ChatMessage.getSpeaker({ user: game.user }),
            casterUuid: null
        };
    }
    const puffer = globalThis._eisenkrallenPuffer;

    // ============================================================
    // 2. Wirkenden (Caster) & QS ermitteln
    // ============================================================
    const casterActor = (typeof testData !== "undefined" && testData?.actor) || 
                        (typeof testData !== "undefined" && testData?.speaker?.actor ? game.actors.get(testData.speaker.actor) : null) || 
                        (typeof testData !== "undefined" && testData?.speaker?.token ? canvas.tokens.get(testData.speaker.token)?.actor : null) || 
                        actor || 
                        canvas.tokens.controlled[0]?.actor || 
                        game.user.character;

    if (!casterActor) {
        ui.notifications.warn("Kein Akteur gefunden!");
        return;
    }

    puffer.casterUuid = casterActor.uuid; 

    // QS sicher aus dem Flag holen (für den Klick aus der Chatkarte)
    let flagQs = casterActor.getFlag("world", "letzteGabenQS");
    if (flagQs) {
        puffer.qs = flagQs;
        await casterActor.unsetFlag("world", "letzteGabenQS");
    } else if (typeof testData !== "undefined") {
        const parsedQs = Number(testData?.result?.QL || testData?.qualityStep);
        if (!isNaN(parsedQs) && parsedQs > 0) {
            puffer.qs = parsedQs;
        }
    }

    // ============================================================
    // 3. Ziele sammeln
    // ============================================================
    const targetActor = actor || canvas.tokens.controlled[0]?.actor || game.user.character;
    const targetName = DSK_FW.ResolveTokenName(targetActor);

    if (!puffer.ziele.some(z => z.actor === targetActor)) {
        puffer.ziele.push({ actor: targetActor, name: targetName });
    }

    // ============================================================
    // 4. Verzögerte Auswertung
    // ============================================================
    clearTimeout(puffer.timer);
    puffer.timer = setTimeout(async () => {
        const daten = globalThis._eisenkrallenPuffer;
        delete globalThis._eisenkrallenPuffer;

        if (!daten || daten.ziele.length === 0) return;

        const qs = daten.qs;
        const dauerRunden = qs * 3;
        const dauerText = `${dauerRunden} Kampfrunden (QS ${qs})`;
        const basisBeschreibung = `Die Krallen des Rondrakindes verhärten sich und glänzen metallisch. Während der Wirkungsdauer verursacht das Rondrakind mit seinen Krallen 1W6+3 TP im Nahkampf.`;

        // ============================================================
        // A) SCHLEIFE (Standard Framework v11.2)
        // ============================================================
        for (let zielData of daten.ziele) {

            // Wesen prüfen (Keine Geister, Vampire, Untote, Zombies, Pflanzen)
            const ausgeschlosseneWesen = ["geist", "geister", "vampir", "vampire", "untot", "untote", "zombie", "zombies", "pflanze", "pflanzen"];
            const istLebewesen = !DSK_FW.Wesen.match(zielData.actor, ausgeschlosseneWesen);

            if (!istLebewesen) {
                daten.fehlschläge.push({ name: zielData.name, grund: "Kein Lebewesen" });
                continue;
            }

            // 1. Waffe erzeugen
            const itemData = {
                name: waffenName,
                type: "meleeweapon",
                img: "https://assets.forge-vtt.com/bazaar/systems/dsk/assets/icons/categories/meleeweapon.webp",
                system: {
                    combatskill: "Raufen",
                    tp: "1d6+3",
                    rw: "short",
                    worn: { value: true, wearable: true, wrongGrip: false },
                    price: 0, weight: 0, quantity: 1
                }
            };
            const [createdItem] = await zielData.actor.createEmbeddedDocuments("Item", [itemData]);

            // 2. Effekt über Framework anwenden
            try {
                await DSK_FW.Effekt.Anwenden({
                    name: gabenName,
                    ahne: ahne,
                    beschreibung: basisBeschreibung,
                    gabeZiel: "",
                    qs: qs,
                    ziel: zielData.actor,
                    flags: {
                        dsk: { casterUuid: daten.casterUuid } 
                    }
                });

                const frischErstellterEffekt = zielData.actor.effects.find(e => e.name === gabenName);
                if (frischErstellterEffekt) {
                    await frischErstellterEffekt.update({ "duration.rounds": dauerRunden });

                    // --- DEIN HOOK FÜR DAS SAUBERE LÖSCHEN ---
                    Hooks.once("deleteActiveEffect", async (deletedEffect) => {
                        if (!frischErstellterEffekt || deletedEffect.id !== frischErstellterEffekt.id) return;
                        if (createdItem) {
                            await zielData.actor.deleteEmbeddedDocuments("Item", [createdItem.id]);
                        }
                    });
                }

                daten.erfolge.push(zielData.name);
            } catch (e) {
                console.warn(`Fehler bei ${zielData.name}:`, e);
                daten.fehlschläge.push({ name: zielData.name, grund: "Framework-Fehler" });
            }
        }

        // ============================================================
        // B) ERFOLGS/FEHLSCHLAG-CHATKARTE
        // ============================================================
        let erfolgHtml = daten.erfolge.length > 0 ? `
            <div style="margin-top: 10px; margin-bottom: 10px;">
                <p><span style="color:#18940F; font-weight:bold;">Erfolg</span></p>
                <ul class="dsklist" style="margin-top:0;">${daten.erfolge.map(n => `<li>${n}</li>`).join("")}</ul>
            </div>` : "";

        let fehlschlagHtml = "";
        if (daten.fehlschläge.length > 0) {
            let inhalt = daten.fehlschläge.map(f => `<li style="font-size:0.9em;">${f.name} (${f.grund})</li>`).join("");
            fehlschlagHtml = `<hr><div style="margin-top:10px;"><p><span style="color:#B30000; font-weight:bold;">Fehlschlag</span></p><ul class="dsklist">${inhalt}</ul></div>`;
        }

        ChatMessage.create({
            speaker: { alias: "System" },
            content: `
                ${DSK_FW.UI.Header(gabenName, DSK_FW.Symbol(ahne))}
                <div class="dskbox2" style="margin-top:10px;">
                    <p><b>Gabenwirkung:</b></p>
                    <p>${basisBeschreibung}</p>
                    ${erfolgHtml}
                    ${fehlschlagHtml}
                    <hr>
                    <p style="text-align:center; font-weight:bold;">Wirkungsdauer:<br>${dauerText}</p>
                </div>
            `
        });
    }, 300);
})();
